predicted_python:
import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find modalities for the 'U19 Thalamus in the Middle' project
agg_pipeline = [
    {
        "$match": {
            "data_description.project_name": {
                "$regex": "Thalamus in the [Mm]iddle", 
                "$options": "i"
            }
        }
    },
    {
        "$project": {
            "modality": "$data_description.modality.name",
            "project_name": "$data_description.project_name"
        }
    },
    {
        "$group": {
            "_id": "$modality",
            "count": {"$sum": 1}
        }
    },
    {
        "$sort": {"_id": 1}
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)
print("Modalities of assets for the 'U19 Thalamus in the Middle' project:")
print(json.dumps(result, indent=3))

target_python:
import json
from aind_data_access_api.document_db import MetadataDbClient

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

agg_pipeline = [
    {
        "$match": {
            "data_description.modality": {"$exists": True, "$ne": []},
            "subject.subject_id": {"$exists": True, "$ne": None}
        }
    },
    {
        "$project": {
            "subject_id": "$subject.subject_id",
            "modalities": "$data_description.modality.name"
        }
    },
    {"$unwind": "$modalities"},
    {
        "$group": {
            "_id": {"subject_id": "$subject_id", "modality": "$modalities"}
        }
    },
    {
        "$group": {
            "_id": "$_id.subject_id",
            "unique_modalities": {"$addToSet": "$_id.modality"},
            "modality_count": {"$sum": 1}
        }
    },
    {
        "$match": {
            "modality_count": {"$gte": 3}
        }
    },
    {
        "$project": {
            "_id": 0,
            "subject_id": "$_id",
            "unique_modalities": 1,
            "modality_count": 1
        }
    },
    {"$sort": {"modality_count": -1}},
    {"$limit": 5}
]

result = docdb_api_client.aggregate_docdb_records(pipeline=agg_pipeline)
print(json.dumps(result, indent=2))

