predicted_answer:
import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find 5 subject IDs that appear in 3 different assets with different modalities
agg_pipeline = [
    # Project only the fields we need
    {
        "$project": {
            "subject_id": "$subject.subject_id",
            "modality": {"$arrayElemAt": ["$data_description.modality.name", 0]}
        }
    },
    # Filter out documents with missing subject_id or modality
    {
        "$match": {
            "subject_id": {"$exists": True, "$ne": None},
            "modality": {"$exists": True, "$ne": None}
        }
    },
    # Group by subject_id and modality to count unique combinations
    {
        "$group": {
            "_id": {"subject_id": "$subject_id", "modality": "$modality"},
            "count": {"$sum": 1}
        }
    },
    # Group by subject_id to count distinct modalities
    {
        "$group": {
            "_id": "$_id.subject_id",
            "modality_count": {"$sum": 1},
            "modalities": {"$push": "$_id.modality"}
        }
    },
    # Filter subjects with at least 3 different modalities
    {
        "$match": {
            "modality_count": {"$gte": 3}
        }
    },
    # Limit to 5 results
    {
        "$limit": 5
    },
    # Format the output
    {
        "$project": {
            "_id": 0,
            "subject_id": "$_id",
            "modality_count": 1,
            "modalities": 1
        }
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)

print(json.dumps(result, indent=3))

