import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Find documents related to the brain computer interface project
# and extract unique viruses from the procedures section
pipeline = [
    {
        "$match": {
            "data_description.project_name": {"$regex": "brain computer interface", "$options": "i"}
        }
    },
    {
        "$unwind": {
            "path": "$procedures.subject_procedures",
            "preserveNullAndEmptyArrays": False
        }
    },
    {
        "$match": {
            "procedures.subject_procedures.procedure_type": "virus_injection"
        }
    },
    {
        "$group": {
            "_id": "$procedures.subject_procedures.virus.name",
            "count": {"$sum": 1},
            "details": {"$first": "$procedures.subject_procedures.virus"}
        }
    },
    {
        "$sort": {"_id": 1}
    }
]

result = docdb_api_client.aggregate_docdb_records(pipeline=pipeline)
print(json.dumps(result, indent=3))

