import json
import matplotlib.pyplot as plt
import pandas as pd
from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# First, let's get all data from the "Thalamus in the middle" project
# and extract the genotype information
agg_pipeline = [
    {
        "$match": {
            "data_description.project_name": {"$regex": "Thalamus in the middle", "$options": "i"}
        }
    },
    {
        "$group": {
            "_id": "$subject.genotype",
            "count": {"$sum": 1}
        }
    },
    {
        "$sort": {"count": -1}
    }
]

result = docdb_api_client.aggregate_docdb_records(pipeline=agg_pipeline)
print("Genotype distribution in 'Thalamus in the middle' project:")
print(json.dumps(result, indent=3))

# Convert to pandas DataFrame for visualization
df = pd.DataFrame(result)
if not df.empty:
    # Rename columns for clarity
    df = df.rename(columns={"_id": "Genotype"})

    # Create a bar chart
    plt.figure(figsize=(10, 6))
    plt.bar(df["Genotype"], df["count"])
    plt.title("Genotype Distribution in 'Thalamus in the middle' Project")
    plt.xlabel("Genotype")
    plt.ylabel("Count")
    plt.xticks(rotation=45, ha="right")
    plt.tight_layout()
    plt.show()

    # Calculate percentages
    total = df["count"].sum()
    df["percentage"] = (df["count"] / total * 100).round(2)
    print("\nGenotype distribution with percentages:")
    print(df)
else:
    print("No data found for the specified project.")

